void display(uint16_t x_init, uint16_t y_init, uint16_t heng, uint16_t lie,const unsigned char *paint) {
    uint16_t i,j;
    const unsigned char *data = paint;
    for (i = 0; i < heng; i++) {
        for (j = 0; j < lie; j++) {
            // 检查是否超出屏幕边界
            if ((x_init + j * 6) < lcddev.width && (y_init + i * 12) < lcddev.height) {
                delay_us(250);
                lcd_show_char(x_init + j * 6, y_init + i * 12, (char)(*data++), 12, 0, BLACK);
                delay_us(250);
            } else {
                data++; // 即使不显示也要移动指针
            }
        }
    }
}

